/* The original color photograph is rendered through an alpha-only portrait mask. */
.hero{display:grid;grid-template-rows:minmax(0,1fr) auto;justify-content:initial;min-height:720px;height:100svh;max-height:1150px}
.hero-content{height:100%;min-height:0;grid-template-columns:minmax(0,1.05fr) minmax(0,.95fr);gap:clamp(36px,5.5vw,95px);padding-top:24px;padding-bottom:24px;align-items:center}
.hero-bottom{position:relative;inset:auto;min-height:100px;padding-top:25px;padding-bottom:27px}
.portrait-block{position:relative;isolation:isolate;justify-self:end;align-self:center;width:min(100%,calc((100svh - 168px)*.75));max-width:510px;margin:0;pointer-events:none}
.portrait-block:before{content:"";position:absolute;inset:14% -21% -8%;border:0;border-radius:50%;background:radial-gradient(ellipse at 49% 54%,#77c9b025 0%,#6ebda712 34%,transparent 68%);filter:blur(26px);z-index:-1}
.portrait-block:after{display:none}
.portrait-panel{padding:0;border:0;background:none;box-shadow:none;position:relative}
.portrait-image{width:100%;height:auto;max-height:none;aspect-ratio:3/4;object-fit:fill;object-position:center;display:block;border-radius:0;filter:none;-webkit-mask-image:var(--portrait-alpha),linear-gradient(to bottom,#000 0%,#000 77%,#000b 87%,transparent 100%);mask-image:var(--portrait-alpha),linear-gradient(to bottom,#000 0%,#000 77%,#000b 87%,transparent 100%);-webkit-mask-size:100% 100%;mask-size:100% 100%;-webkit-mask-repeat:no-repeat;mask-repeat:no-repeat;-webkit-mask-composite:source-in;mask-composite:intersect}
@media(min-width:1700px){.portrait-block{max-width:540px}.hero-content{gap:90px}}
@media(max-width:1150px){.hero{min-height:740px}.hero-content{grid-template-columns:minmax(0,1.05fr) minmax(0,.95fr);gap:32px;padding-block:24px}.portrait-block{width:100%;max-width:440px;margin:0}.portrait-block:before{inset:14% -15% -6%;border:0}.hero-bottom{min-height:100px}}
@media(max-width:850px) and (min-width:651px){.hero{height:auto;min-height:max(820px,100svh)}.hero-content{grid-template-columns:minmax(0,1.1fr) minmax(0,.9fr);gap:24px;min-height:700px;padding-block:45px}.portrait-block{width:100%;max-width:330px}.hero-bottom{min-height:100px}}
@media(max-height:800px) and (min-width:851px){.hero{min-height:720px}.hero-content{padding-top:22px;padding-bottom:22px}.portrait-block{width:min(100%,calc((100svh - 168px)*.75));max-width:440px}.portrait-image{max-height:none;object-position:center}.hero-bottom{min-height:100px}}
@media(max-width:650px){.hero{height:auto;min-height:100svh;max-height:none;grid-template-rows:1fr auto}.hero-content{height:auto;min-height:0;grid-template-columns:minmax(0,1fr) 43%;gap:18px;padding-top:35px;padding-bottom:34px;align-items:start}.portrait-block{width:100%;max-width:none;grid-column:2;grid-row:1;margin:26px -3px 0 0;align-self:start}.portrait-block:before{inset:11% -35% -15%;filter:blur(17px);border:0}.portrait-image{aspect-ratio:3/4;max-height:none}.hero-title-group{grid-column:1;grid-row:1}.hero-bio{margin-top:8px}.hero-bottom{min-height:0;padding-top:24px;padding-bottom:20px}.hero-actions{margin-top:4px}.hero-kicker{margin-bottom:22px}.signal-field{opacity:1}}
@media(max-width:380px){.hero-content{padding-top:30px;grid-template-columns:minmax(0,1fr) 42%;gap:14px}.portrait-block{margin-top:27px}.hero-bio{font-size:12px}}
.portrait-image{mask-mode:alpha,alpha}
.desktop-hero{display:none}
@media(min-width:901px){
 .mobile-hero{display:none}
 .desktop-hero{display:block;position:relative;isolation:isolate;height:100svh;min-height:640px;overflow:hidden;background:#081b20;container-type:inline-size;color:#edf1eb;font-family:Arial,"Microsoft YaHei","PingFang SC",sans-serif}
 .desktop-stage{position:absolute;left:50%;top:50%;width:100%;aspect-ratio:1586/992;transform:translate(-50%,-50%);container-type:inline-size}
 .desktop-art,.desktop-backdrop,.desktop-reference-art{position:absolute;inset:0;pointer-events:none;display:block}
 .desktop-art{z-index:-1}
 .desktop-backdrop img,.desktop-reference-art img{display:block;width:100%;height:100%;object-fit:fill}
 .desktop-backdrop{mask-image:linear-gradient(to bottom,#000 0%,#000 84%,transparent 87%)}
 .desktop-reference-art{mask-image:linear-gradient(to right,transparent 39%,#000 44%),linear-gradient(to bottom,transparent 8%,#000 16%,#000 78%,transparent 86.5%);mask-composite:intersect;mask-mode:alpha,alpha}
 .desktop-kicker,.desktop-name,.desktop-name-en,.desktop-role,.desktop-goal,.desktop-focus,.desktop-actions{position:absolute;margin:0;white-space:nowrap}
 .desktop-kicker{left:6.43%;top:16.35%;display:flex;align-items:center;gap:1.05cqw;height:1.9cqw;font-size:.90cqw;letter-spacing:.235cqw;line-height:1.6;font-weight:400;color:#a4d4c9}
 .desktop-kicker:before{content:"";width:3.15cqw;border-top:1px solid #b0d5c7;flex:none}
 .desktop-name{left:6.54%;top:22.60%;font-size:7.82cqw;line-height:1.15;font-weight:400;letter-spacing:.04em}
 .desktop-name-en{left:6.80%;top:38.15%;font-size:1.18cqw;line-height:1.6;letter-spacing:.35cqw;color:#d3ddd8}
 .desktop-role{left:6.72%;top:45.10%;font-size:2.80cqw;line-height:1.5;font-weight:400;letter-spacing:.015em;transform:scaleY(.94);transform-origin:top left}
 .desktop-goal{left:6.65%;top:52.95%;font-size:1.24cqw;line-height:1.9;letter-spacing:0;color:#ccd7d1}
 .desktop-focus{left:6.71%;top:57.45%;font-size:1.23cqw;line-height:1.9;letter-spacing:0;color:#cbd7d2}
 .desktop-actions{left:6.65%;top:65.45%;display:flex;align-items:center;gap:1.14cqw}
 .desktop-link{display:inline-flex;align-items:center;justify-content:center;gap:1.30cqw;width:12.61cqw;height:3.91cqw;min-height:44px;font-size:1.16cqw;line-height:1.6;border:1px solid #a4bdb480;background:transparent;color:#eff2eb;transition:background .18s,color .18s}
 .desktop-link.primary{background:#efac83;border-color:#efac83;color:#162328}
 .desktop-link.secondary{width:13.24cqw}
 .desktop-link.primary:hover{background:#ffc097;border-color:#ffc097}
 .desktop-link.secondary:hover{background:#bad7cc14}
 .desktop-link svg{width:1.90cqw;height:1.90cqw;min-width:16px;min-height:16px}
 .desktop-summary{position:absolute;left:0;right:0;bottom:0;height:12.4%;min-height:82px;border-top:1px solid #c6ddd522;container-type:inline-size;background-color:#0b1d21;background-image:url("assets/home-hero/desktop-background.png");background-size:100% auto;background-position:center bottom;background-repeat:no-repeat}
 .desktop-summary-inner{height:100%;display:grid;grid-template-columns:14.70cqw 16.45cqw 24cqw;padding-left:6.45cqw;padding-top:1.45cqw;align-items:start}
 .desktop-summary-inner>div{height:3.40cqw;min-height:45px;border-left:1px solid #c6ddd560;padding-left:1.45cqw}
 .desktop-summary strong{display:block;font-size:1.12cqw;font-weight:400;line-height:1.6;color:#f0f3ec}
 .desktop-summary span{display:block;font-size:.90cqw;line-height:1.8;color:#c2d0cb;margin-top:.20cqw;white-space:nowrap}
}
@media(prefers-reduced-motion:reduce){.desktop-hero *{transition:none!important}}
:scope{--background:#071217;--home-deep:#050f13;--home-base:#09171c;--home-tone:brightness(.98) contrast(1.06) saturate(1.02);background:var(--home-deep)}
:scope{background:var(--home-deep)}
.mobile-hero{background:radial-gradient(ellipse at 88% 22%,#1b403b66,transparent 45%),radial-gradient(ellipse at 44% 100%,#182d383d,transparent 56%),var(--home-base)}
.mobile-hero:before{background:linear-gradient(90deg,#030b10e0,rgba(4,14,18,.7) 35%,transparent 64%),linear-gradient(0deg,#030c11d1,transparent 34%)}
.mobile-hero:after{opacity:.15}
.mobile-hero .hero-bottom{background:#030b0f24}
@media(min-width:901px){
 .desktop-hero{background:var(--home-deep)}
 .desktop-art{filter:var(--home-tone)}
 .desktop-summary{isolation:isolate;background:var(--home-deep)}
 .desktop-summary:before{content:"";position:absolute;inset:0;z-index:-1;pointer-events:none;background-image:url("assets/home-hero/desktop-background.png");background-size:100% auto;background-position:center bottom;background-repeat:no-repeat;filter:var(--home-tone)}
}
}

.home-intro{position:relative;scroll-margin-top:0}
.home-page .portfolio-header.at-home{visibility:hidden;pointer-events:none;transform:translateY(-100%)}
.home-page .portfolio-header{transition:background .25s,color .25s,transform .25s,visibility .25s}
